import { BENEFIT_RULESET, BENEFIT_SOURCES, BENEFIT_CATEGORIES, BENEFIT_STATUS, BENEFIT_SUMMARIES, BENEFITS, GRADES, OTHER_SUPPORT, RESIDENTIAL_SURCHARGES, COMBINATION_RULES, benefitAmount, benefitById } from './benefits-data.js';
import { RULESET } from './data.js';
import { icon, escapeHTML as esc } from './ui.js';
export const euro=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n)+' €';
const unitLabels={month:'Monat',year:'Kalenderjahr',measure:'Maßnahme'};
const sources=ids=>`<p class="benefit-sources">Grundlage: ${ids.map(id=>`<a href="${BENEFIT_SOURCES[id].url}" target="_blank" rel="noopener noreferrer">${esc(BENEFIT_SOURCES[id].title)}</a>`).join(' · ')}</p>`;
export function gradeDisplay(grade){
  const g=GRADES[grade-1],min=RULESET.gradeThresholds[grade],max=grade===5?100:RULESET.gradeThresholds[grade+1],number=n=>new Intl.NumberFormat('de-DE').format(n);
  return `<h2>Pflegegrad ${grade}</h2><p>${g.description}</p><details class="compact-details"><summary>Einordnung verstehen</summary><div class="details-body"><p class="grade-threshold">${number(min)} ${grade===5?'bis':'bis unter'} ${number(max)} Punkte bei der Begutachtung.</p><p>Entscheidend sind gesundheitlich bedingte Einschränkungen der Selbstständigkeit und Fähigkeiten, die voraussichtlich mindestens sechs Monate bestehen. Eine Diagnose oder das Alter allein bestimmen den Pflegegrad nicht. Besondere Bedarfskonstellationen können Pflegegrad 5 auch unter 90 Punkten begründen; das muss fachlich beurteilt werden.</p><a href="#/quellen">Bewertung und Quellen</a></div></details>`;
}
function statusList(grade){
  return `<ul class="benefit-status-list">${BENEFIT_CATEGORIES.map(c=>{const status=c.statuses[grade-1],info=BENEFIT_STATUS[status],note=grade===1&&c.grade1Note?c.grade1Note:info.label;return `<li data-category="${c.id}" data-status="${status}"><span class="benefit-category-label">${icon(c.icon)}<span>${c.label}</span></span><span class="benefit-status status-${status}" title="${esc(note)}"><span aria-hidden="true">${info.symbol}</span><span class="sr-only">${esc(note)}</span></span></li>`;}).join('')}</ul>`;
}
function gradeCards(grade){
  return `<div class="benefit-grade-selector" role="group" aria-label="Pflegegrad auswählen – Leistungen zu Hause">${GRADES.map(g=>`<article class="benefit-grade-card grade-tone-${g.grade}"><button data-benefit-grade="${g.grade}" aria-label="Pflegegrad ${g.grade} auswählen: ${g.short}" aria-pressed="${g.grade===grade}" aria-controls="benefit-content"><span class="grade-choice-top">Pflegegrad <strong>${g.grade}</strong></span><span class="grade-choice-description">${g.short}</span><span class="grade-choice-link">Auswählen ${icon('arrow')}</span></button>${statusList(g.grade)}</article>`).join('')}</div>`;
}
const statusLegend=()=>`<div class="benefit-status-legend" aria-label="Bedeutung der Statussymbole">${Object.entries(BENEFIT_STATUS).map(([key,v])=>`<span><span class="benefit-status status-${key}" aria-hidden="true">${v.symbol}</span>${key==='conditional'?'Bei besonderem Bedarf':v.label}</span>`).join('')}</div>`;
function benefitCard(b,grade){
  const amount=benefitAmount(b.id,grade),unavailable=amount===null;
  const notAvailable=b.id==='annual'?'Kein eigenes Jahresbudget':'Kein eigener Anspruch';
  const noDescription=b.id==='annual'?'Kurzzeitpflege kann aus dem Entlastungsbetrag bezahlt werden. Dadurch entsteht kein zusätzliches Budget.':'Diese Leistung gibt es regulär ab Pflegegrad 2.';
  return `<article class="benefit-card tone-${unavailable?'stone':b.tone} ${unavailable?'benefit-unavailable':''}" data-benefit="${b.id}" data-kind="${b.kind}" data-available="${!unavailable}"><div class="benefit-card-head">${icon(b.icon)}<h3>${b.title}</h3></div>${unavailable?`<p class="benefit-unavailable-title">${notAvailable}</p>`:`<p class="benefit-amount">${b.cap?'<span class="amount-prefix">Bis zu</span>':''}<strong>${euro(amount)}</strong><span class="amount-unit">/ ${unitLabels[b.unit]}</span></p><p class="benefit-tag">${b.tag}</p>`}<p class="benefit-card-description">${unavailable?noDescription:esc(BENEFIT_SUMMARIES[b.id])}</p><details><summary>Mehr erfahren</summary><div class="details-body">${unavailable?`<p>Für Pflegegrad 1 besteht kein eigener Anspruch auf ${b.id==='annual'?'den gemeinsamen Jahresbetrag':b.id==='cash'?'Pflegegeld':'Pflegesachleistungen'}. Der Entlastungsbetrag ist eine eigene, zweckgebundene Kostenerstattung.</p>`:b.details.map(p=>`<p>${esc(p)}</p>`).join('')}${sources(b.sources)}</div></details></article>`;
}
function combinations(grade){
  if(grade===1)return `<details class="benefit-combinations"><summary>Was ist bei Pflegegrad 1 anders?</summary><div class="details-body"><p>Es gibt kein Pflegegeld, kein eigenes Sachleistungsbudget und keinen gemeinsamen Jahresbetrag. Tages- und Kurzzeitpflege können unter den gesetzlichen Voraussetzungen aus dem Entlastungsbetrag bezahlt werden; es entsteht dadurch kein zusätzliches Budget.</p>${sources(['cash','services','annual','relief'])}</div></details>`;
  return `<details class="benefit-combinations"><summary>Welche Leistungen passen zusammen?</summary><div class="details-body"><h3>Pflegegeld + Pflegedienst: anteilig</h3><p>Wenn Sie 50 Prozent der Sachleistung nutzen (${euro(benefitAmount('services',grade)/2)}), bleiben 50 Prozent des Pflegegeldes (${euro(benefitAmount('cash',grade)/2)}) im vollen Monat. An die Wahl des Verhältnisses sind Sie grundsätzlich ${COMBINATION_RULES.bindingMonths} Monate gebunden.</p><h3>Entlastungsbetrag + Tagespflege: zusätzlich</h3><p>Diese Leistungen kürzen das Pflegegeld und den ambulanten Sachleistungsanspruch nicht. Jede Rechnung darf nur einmal erstattet werden. Die Voraussetzungen der einzelnen Leistungen gelten weiterhin.</p><h3>Mehr Alltagshilfe aus dem Sachleistungsbudget</h3><p>Bis zu ${COMBINATION_RULES.conversionMaximumShare*100} Prozent der ungenutzten monatlichen Sachleistung können für nach Landesrecht anerkannte Alltagshilfe verwendet werden: bei Pflegegrad ${grade} höchstens ${euro(Math.round(benefitAmount('services',grade)*COMBINATION_RULES.conversionMaximumShare*100)/100)}. Das ist kein zusätzliches Budget. Die Umwandlung gilt als Sachleistungsnutzung und mindert das Pflegegeld anteilig; Pflegedienstkosten werden zuerst berücksichtigt.</p><h3>Ersatzpflege + Kurzzeitpflege: ein Jahrestopf</h3><p>Zusammen sind bis zu ${euro(benefitAmount('annual',grade))} im Kalenderjahr verfügbar. Das Pflegegeld wird während dieser Pflegearten grundsätzlich zur Hälfte weitergezahlt. Einzelheiten stehen in der entsprechenden Leistungskachel.</p>${sources(['combination','conversion','day','relief','annual','cash'])}</div></details>`;
}
export function benefitsContent(grade,setting='home'){
  const mainIds=['relief','cash','services','annual','aids','home'];
  return `${setting==='home'?`<section class="mobile-benefit-matrix" aria-label="Leistungsarten für Pflegegrad ${grade} zu Hause"><h2>Pflegegrad ${grade} · Leistungen zu Hause</h2>${statusList(grade)}${statusLegend()}</section>`:''}<div id="grade-display" class="benefit-grade-intro">${gradeDisplay(grade)}</div>
  <div class="care-setting" role="group" aria-label="Pflegeort"><button data-care-setting="home" aria-pressed="${setting==='home'}">Zu Hause</button><button data-care-setting="residential" aria-pressed="${setting==='residential'}">Im Pflegeheim</button></div>
  ${setting==='home'?`<p class="benefit-context">${grade===1?'Für anerkannte Unterstützung im Alltag. Kein Pflegegeld bei Pflegegrad 1.':'Pflegegeld oder Pflegedienst – auch anteilig kombinierbar.'}</p><div class="benefits-grid primary-benefits">${mainIds.map(id=>benefitCard(benefitById(id),grade)).join('')}</div>${combinations(grade)}
  ${grade>1?`<details class="more-benefits"><summary>Zusätzlich: Tages- & Nachtpflege</summary><div class="benefits-grid">${BENEFITS.filter(b=>b.id==='day').map(b=>benefitCard(b,grade)).join('')}</div></details>`:''}
  <details class="more-benefits other-support"><summary>Beratung, Pflegekurse & besondere Wohnformen</summary><div class="details-body">${OTHER_SUPPORT.map(item=>`<details><summary>${item.title}</summary><div class="details-body"><p>${esc(item.text)}</p>${sources(item.sources)}</div></details>`).join('')}</div></details>`:`<p class="benefit-context">Ein Zuschuss zu den Pflegekosten – die Heimrechnung kann höher sein.</p><div class="benefits-grid residential-grid">${benefitCard(benefitById('residential'),grade)}${grade>1?`<section class="residential-share"><h3>Weniger Eigenanteil mit der Zeit</h3><dl>${RESIDENTIAL_SURCHARGES.bands.map((band,i)=>`<div><dt>${i===0?`Bis ${RESIDENTIAL_SURCHARGES.bands[1].afterMonths}`:`Über ${band.afterMonths}`} Monate</dt><dd>${band.share*100} %</dd></div>`).join('')}</dl><p>Zuschlag zum pflegebedingten Eigenanteil. Unterkunft, Verpflegung und Investitionskosten zählen nicht dazu.</p><details><summary>Wie wird das berücksichtigt?</summary><div class="details-body"><p>Maßgeblich ist die Dauer des Bezugs vollstationärer Leistungen. Angefangene Monate zählen mit. Die Pflegekasse berechnet den Zuschlag und zahlt ihn an die Einrichtung; Sie erhalten die Rechnung über den verbleibenden Eigenanteil.</p>${sources(['surcharge'])}</div></details></section>`:''}</div>`}
  <div class="benefit-next"><a class="button primary" href="#/ratgeber">Pflegegrad beantragen ${icon('arrow')}</a><a class="text-link" href="#guide-apply">Leistungen mit der Pflegeberatung planen ${icon('arrow')}</a></div>`;
}
export function benefitsPage(grade=2,setting='home'){
  return `<div class="page benefits-page route-enter"><header class="page-header"><p class="eyebrow">Leistungen & Budgets</p><h1>Welche Hilfe steht mir zu?</h1><p class="lead">Wählen Sie einen Pflegegrad.</p></header>
  <p class="grade-matrix-heading">Leistungsarten bei Pflege zu Hause</p>${gradeCards(grade)}
  <div class="desktop-status-legend">${statusLegend()}</div><p class="shared-budget-hint">Pflegegrad 1: Kurzzeitpflege nur über den Entlastungsbetrag. Ab Pflegegrad 2: Verhinderungs- und Kurzzeitpflege teilen sich ein Jahresbudget.</p>
  <p class="benefit-eligibility">Nach Anerkennung und bei erfüllten Voraussetzungen. Keine Gesamtauszahlung.</p>
  <div id="benefit-content">${benefitsContent(grade,setting)}</div>
  <details class="benefit-method"><summary>Rechtsstand, Quellen & Reform 2027</summary><div class="details-body"><p><strong>${BENEFIT_RULESET.label}.</strong> Die Beträge sind in einer getrennten, versionierten Datenstruktur hinterlegt. Dieser Stand wird nicht automatisch aktualisiert.</p><p>Die Übersicht beschreibt die soziale Pflegeversicherung. Die private Pflegepflichtversicherung muss gleichwertige Leistungen vorsehen; Abrechnung und gegebenenfalls Beihilfeanteile klären Sie mit Ihrem Versicherer. Sonderregeln, etwa für bestimmte Wohnformen, sind gesondert zu prüfen.</p><p>Die PNOG-Reform ist nach der ersten Lesung vom 5. November 2026 weiterhin im parlamentarischen Verfahren. Geplante Budgets sind hier nicht eingerechnet. Aus den geprüften Quellen ergeben sich keine bereits verbindlichen PNOG-Leistungsbeträge für 2027.</p><a href="#/reform">Geltendes Recht und Reformpläne unterscheiden →</a><ul class="benefit-source-list">${Object.values(BENEFIT_SOURCES).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul><p>Datenversion: ${BENEFIT_RULESET.id}</p></div></details></div>`;
}
export function benefitsPreview(grade){
  const ids=grade===1?['relief','aids']:['cash','relief','annual'];
  return `<section class="result-benefits"><h2>Welche Leistungen wären möglich?</h2><div class="benefit-preview-grid">${ids.map(id=>{const b=benefitById(id);return `<div class="benefit-preview tone-${b.tone}" data-benefit="${id}"><h3>${b.title}</h3><p>${b.cap?'<span>Bis zu </span>':''}<strong>${euro(benefitAmount(id,grade))}</strong><span> / ${unitLabels[b.unit]}</span></p><span class="benefit-tag">${b.tag}</span></div>`;}).join('')}</div><p class="benefit-eligibility">Erst nach Anerkennung von Pflegegrad ${grade} und bei erfüllten Voraussetzungen. Der Selbstcheck begründet keinen Leistungsanspruch.${grade>1?' Pflegegeld wird bei Nutzung eines Pflegedienstes anteilig gekürzt.':''}</p><a class="text-link" href="#/leistungen" data-benefits-link="${grade}">Alle Leistungen ansehen ${icon('arrow')}</a></section>`;
}
